import{_ as t,o,c as n,a2 as a}from"./chunks/framework.G0y0PQA7.js";const r="/relio/shots/en/start-welcome.png",s="/relio/shots/en/start-update-ask.png",g=JSON.parse('{"title":"Install and open your first file","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/start.md","filePath":"en/quick/start.md"}'),i={name:"en/quick/start.md"};function l(c,e,p,u,d,f){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="install-and-open-your-first-file" tabindex="-1">Install and open your first file <a class="header-anchor" href="#install-and-open-your-first-file" aria-label="Permalink to &quot;Install and open your first file&quot;">​</a></h1><p>Installing Relio, exploring a sample and turning on new version notices takes about five minutes.</p><ol><li><p><strong>Download</strong> — Get the installer <code>Relio_&lt;version&gt;_x64-setup.exe</code> from <a href="https://github.com/relio-hq/relio/releases/latest" target="_blank" rel="noreferrer">Releases</a>. To use Relio without installing, download <code>Relio_&lt;version&gt;_x64_portable.zip</code>, unzip it and run <code>relio.exe</code>.</p></li><li><p><strong>Install</strong> — Run the installer. It installs for the current user only, without administrator rights. If a &quot;Windows protected your PC&quot; window appears, check that the file came from where you expected and click <strong>More info → Run anyway</strong> (the warning appears because the installer is not code-signed yet).</p></li><li><p><strong>First run</strong> — On the start screen, choose New diagram, Open file, Open sample or one of your recent files.</p><figure class="shot" data-scene="start-welcome"><img src="'+r+'" alt="Start screen — New diagram, Open file, Open sample and recent files" loading="lazy"><figcaption>Start screen — New diagram, Open file, Open sample and recent files</figcaption></figure></li><li><p><strong>Open a sample</strong> — Under &quot;Open sample&quot;, pick the PostgreSQL sample (online bookstore) or the MySQL sample (users and permissions). Samples open as a copy, so you can change anything without touching the original.</p></li><li><p><strong>Turn on new version notices</strong> — The first time you run Relio, a bar at the bottom of the window asks whether you want to know when a new version is out. Click <strong>Yes, let me know</strong> and Relio checks the public releases page once a day for version information only. When a new version is available, you can download and install it from inside Relio.</p><figure class="shot" data-scene="start-update-ask"><img src="'+s+'" alt="New version notice bar at the bottom of the window — Yes, let me know / No thanks" loading="lazy"><figcaption>New version notice bar at the bottom of the window — Yes, let me know / No thanks</figcaption></figure></li></ol><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>To turn notices on or off later, change &quot;Check for new versions automatically (once a day)&quot; in Tools › Settings › General. You can check at any time with Help › Check for updates….</p></div><p>Supported: Windows 10 and 11 (64-bit). Apart from checking for and downloading new versions (only when you turn it on or check yourself), every feature works without the internet, and Relio never sends usage data or file contents anywhere.</p><p><strong>More</strong> → <a href="/relio/en/features/file">File</a> · <a href="/relio/en/features/update">Updates</a> · <a href="/relio/en/features/preferences">Settings</a> · <a href="/relio/en/features/troubleshooting">Help and troubleshooting</a></p>',6)])])}const m=t(i,[["render",l]]);export{g as __pageData,m as default};
